import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/financial/money101.html","title":"Money101","lang":"en-US","frontmatter":{},"git":{"updatedTime":1671036462000,"contributors":[{"name":"Noei","username":"Noei","email":"logmanxsa@gmail.com","commits":2,"url":"https://github.com/Noei"}],"changelog":[{"hash":"9b113f63eb3ac679a2d1fcfca0e9fcf8d357f185","time":1671036462000,"email":"logmanxsa@gmail.com","author":"Noei","message":"fix content money 101"},{"hash":"b4ebd7a3ce6b1d81c44ad3b58a12e2dc3c5bd3d9","time":1666608859000,"email":"logmanxsa@gmail.com","author":"Noei","message":"Add money101 content"}]},"filePathRelative":"financial/money101.md"}`),a={name:`money101.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="money101" tabindex="-1"><a class="header-anchor" href="#money101"><span>Money101</span></a></h1><h2 id="สองศัพท์สําคัญในโลกการเงิน" tabindex="-1"><a class="header-anchor" href="#สองศัพท์สําคัญในโลกการเงิน"><span>สองศัพท์สำคัญในโลกการเงิน</span></a></h2><ul><li>สภาพคล่อง มีกินมีใช้เหลือเก็บ <strong>ถ้าให้ดีต้องมีเหลือเก็บอย่างน้อย 10 %</strong> ของรายได้ทุกบาทที่เข้ากระเป๋า</li><li>สภาพคล่องที่สะสมในทรัพสินรูปแบบต่าง ๆ ต้องบริหารสภาพคล่องทุกเดือนให้เป็นบวก</li></ul><h3 id="เทคนิคการออม" tabindex="-1"><a class="header-anchor" href="#เทคนิคการออม"><span>เทคนิคการออม</span></a></h3><ul><li>เก็บเศษเหรียญ 5, 10 ไว้ออม ส่วนพวกเหรียญ 1, 2 เก็บไปหยอดตู้ทำบุญ หรือ จะเพิ่ม Challange อื่น ๆ อีกก็ตามใจ</li><li>เก็บภาษีฟุ่มเฟย 10% อยากซื้อไรที่ฟุ่มเฟยก็ซื้อไปแต่หลังซื้อเสร็จต้องหักเข้ากระเป๋าภาษี 10%</li></ul><h2 id="เป้าหมายแรกของการออม" tabindex="-1"><a class="header-anchor" href="#เป้าหมายแรกของการออม"><span>เป้าหมายแรกของการออม</span></a></h2><ul><li><strong>Emergency Basket</strong> สำหรับเหตุไม่คาดฝันที่อาจส่งผลการทบกับการเงิน เช่น ตกงาน เจ็บปวย บลา ๆ</li><li><strong>Retirement Basket</strong> ไว้ใช้ยามเกษียณจากการทำงาน เน้นทยอยสะสมและลงทุนในเครื่่องมือกลุ่มตราสารเงิน ใช้วิธีการลงทุนเรียบง่ายไม่ซับซ้อน</li><li><strong>Money Freedom Basket</strong> เงินที่จะนำไปลงทุนในทรัพย์สินที่สร้างกระแสเงินสดเพื่อสร้างความมั่งคั่งอย่างรวดเร็ว</li></ul><p>Emergency Basket ควรมี 6 - 12 เท่าของรายจ่ายรวมต่อเดือน เงินก้อนนี้ต้องเก็บไว้ในที่ที่มีสภาพคล่องสูล และมูลค่าไม่ผันผวน ไม่เพิ่มหรือลดลงตาภาวะตลาด เช่น</p><ul><li><strong>เงินฝาก</strong> เช่น ออมทรัพย์ ฝากประจำ สหกรณ์ออมทรัพย์</li><li><strong>กองทุนรวมตลาดเงิน</strong> หรือ <strong>กองทุนตราสานหนี้</strong> พวกนี้สภาพคล่องใช้ได้ถอนวันนี้พรุ่งนี้ได้เงิน ความเสี่ยงต่ำ</li><li><strong>สลากออมสิน</strong> และ <strong>สลากออมทรัพย์ ธนาคารเพื่อการเกษตรและสหกรณ์</strong> เหมาะสำหรับคนที่อยากเก็บเงินแล้วก็ลุ้นโชคไปด้วย</li></ul><h2 id="วางแผนรับมือกับเรื่องร้าย-ๆ" tabindex="-1"><a class="header-anchor" href="#วางแผนรับมือกับเรื่องร้าย-ๆ"><span>วางแผนรับมือกับเรื่องร้าย ๆ</span></a></h2><h3 id="ประกันชีวิต" tabindex="-1"><a class="header-anchor" href="#ประกันชีวิต"><span>ประกันชีวิต</span></a></h3><p>หลักการคำนวนเงินทุนประกัน โดยพิจารณาความจำเป็น เป็นเกณฑ์ตัดสินใจสามารถเขียนเป็นสมาการเพื่อการคำนวนอย่างง่าย ๆ ได้ดังนี้</p><table><tr><td rowspan="2">ทุนประกันที่จำเป็น</td><td><b>= (ความจำเป็น - ทรัพย์สินและทุนประกันที่มี)</b></td></tr><tr><td><b>= (ภาระหนี้สิน + มรดก) - (ทรัพย์สิน + ทุนประกันที่มี)</b></td></tr></table><h3 id="ตัวอย่างการคํานวนทุนประกันชีวิต" tabindex="-1"><a class="header-anchor" href="#ตัวอย่างการคํานวนทุนประกันชีวิต"><span>ตัวอย่างการคำนวนทุนประกันชีวิต</span></a></h3><table><tr><td rowspan="7">ความจำเป็น</td><td rowspan="3">ภาระหนี้</td><td>หนี้สหกรณ์ออมทรัพย์</td><td>2,000,000</td></tr><tr><td>หนี้บัตรเครดิต</td><td>300,000</td></tr><tr><td>รวมภาระหนี้</td><td>2,300,000</td></tr><tr><td rowspan="3">มรดก</td><td>ค่าเล่าเรียนลูก</td><td>1,000,000</td></tr><tr><td>เงินตั้งตัว</td><td>1,000,000</td></tr><tr><td>รวมมรดก</td><td>2,000,000</td></tr></table><table><tr><td rowspan="9">ทรัพย์สินและทุนประกันที่มี</td><td rowspan="5">ทรัพย์สิน</td><td>เงินออม</td><td>200,000</td></tr><tr><td>กองทุนสำรองเลี้ยงชีพ</td><td>300,000</td></tr><tr><td>กองทุนรวมเพื่อการเลี้ยงชีพ</td><td>100,000</td></tr><tr><td>บ้าน</td><td>2,400,000</td></tr><tr><td>รวมทรัพย์สิน</td><td>3,000,000</td></tr><tr><td colspan="4"></td></tr><tr><td rowspan="3">ทุนประกันที่มี</td><td>ทุนประกันกลุ่มบริษัท</td><td>300,000</td></tr><tr><td>ทุนประกันส่วนตัว</td><td>0</td></tr><tr><td>รวมทุนประกันที่มี</td><td>300,000</td></tr></table><h3 id="ทุนประกันส่วนตัวที่ควรมีสําหรับกรณีดังตัวอย่าง" tabindex="-1"><a class="header-anchor" href="#ทุนประกันส่วนตัวที่ควรมีสําหรับกรณีดังตัวอย่าง"><span>ทุนประกันส่วนตัวที่ควรมีสำหรับกรณีดังตัวอย่าง</span></a></h3><p>= (ภาระหนี้สิน + มรดก) - (ทรัพสินย์ที่มี + ทุนประกันที่มี)<br> = (2,300,000 + 2,000,000) - (3,000,000 + 300,000)<br> = 4,300,000 - 3,300,000<br> = 1,000,000</p><h2 id="keyword" tabindex="-1"><a class="header-anchor" href="#keyword"><span>Keyword</span></a></h2><p>บัญชีเงินฝากประจำ, กองทุนรวมตลาดเงิน, กองทุนตราสานหนี้</p>`,20)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};